package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"os"
	"sync"
)

// Internal messages for node-to-node communication
type internalMessage struct {
	Type string `json:"type"`
}

func (m internalMessage) String() string {
	b, _ := json.Marshal(m)
	return string(b)
}

// Broadcast request/response
type broadcastRequest struct {
	MsgID int      `json:"msg_id"`
	Value int      `json:"value,omitempty"` // "message" becomes "value" for clarity
}

type broadcastResponse struct {
	InReplyTo int `json:"in_reply_to"`
}

// Read request/response
type readRequest struct {
	MsgID int `json:"msg_id"`
}

type readResponse struct {
	InReplyTo   int    `json:"in_reply_to"`
	Messages    []int  `json:"messages"`
}

// Topology request/response
type topologyRequest struct {
	MsgID int `json:"msg_id"`
}

type topologyResponse struct {
	InReplyTo int `json:"in_reply_to"`
}

// Node state
type nodeState struct {
	values   map[int]int    // value -> timestamp
	hasValue bool           // whether this node should broadcast its values to others
	wg       sync.WaitGroup
	cancel   chan struct{}
	nodeID   string
	nodes   []string        // all node IDs for broadcasting
}

// Node communication channels
type connection struct {
	peerNode    *nodeState
	nodeChannels map[int]*bufio.Writer
	channelCount int
}

// Global connections between nodes
var (
	nodeConnections = make(map[string]*connection)
	connMutex       sync.RWMutex
)

func init() {
	fmt.Fprintf(os.Stderr, "Started broadcast node\n")
}

func handleMessage(r *bufio.Reader) interface{} {
	line, err := r.ReadString('\n')
	if err != nil {
		fmt.Fprintf(os.Stderr, "read error: %v\n", err)
		return nil
	}

	var msg struct {
		Type string `json:"type"`
	}
	json.Unmarshal([]byte(line), &msg)

	switch msg.Type {
	case "broadcast":
		br := broadcastRequest{}
		json.Unmarshal([]byte(line), &br)
		br.Value = br.MsgID // Use msg_id as the value for simplicity in testing

		state.storeValue(br.Value, br.MsgID)

		// Send to all connected nodes
		sendToPeers("broadcast", br.Value, br.MsgID)

		resp := broadcastResponse{InReplyTo: br.MsgID}
		return resp

	case "read":
		rq := readRequest{}
		json.Unmarshal([]byte(line), &rq)

		values := state.getAllValues()

		resp := readResponse{
			InReplyTo:   rq.MsgID,
			Messages:    values,
		}
		return resp

	case "topology":
		tq := topologyRequest{}
		json.Unmarshal([]byte(line), &tq)

		// Store the initial topology so we know all nodes exist
		state.nodes = tq.Topology["*"] // Handle empty case

		resp := topologyResponse{InReplyTo: tq.MsgID}
		return resp

	case "init":
		initMsg := struct {
			NodeID       string `json:"node_id"`
			OtherNodes   []string `json:"other_nodes"`
		}{}
		json.Unmarshal([]byte(line), &initMsg)

		state.nodeID = initMsg.NodeID

		// Build list of all nodes (including self)
		if len(initMsg.OtherNodes) > 0 {
			state.nodes = append(state.nodes, initMsg.OtherNodes...)
		} else {
			state.nodes = []string{state.nodeID}
		}

		// Initialize connections
		initConnections()

		resp := struct{}{}
		return resp

	default:
		fmt.Fprintf(os.Stderr, "unknown message type: %s\n", msg.Type)
		return nil
	}
}

func (s *nodeState) storeValue(value int, msgID int) {
	s.values[value] = msgID
	if !s.hasValue {
		s.hasValue = true
	}

	// Announce to peers that we now have this value
	sendToPeers("value", value, msgID)
}

func (s *nodeState) getAllValues() []int {
	values := make([]int, 0, len(s.values))
	for v := range s.values {
		values = append(values, v)
	}
	return values
}

// Send an internal message to a peer node
func sendToPeers(msgType string, value int, msgID int) {
	connMutex.Lock()
	defer connMutex.Unlock()

	// Announce new value to all other nodes
	for _, peer := range state.nodes {
		if peer != state.nodeID && peer != "" {
			sendMessage(peer, msgType, value, msgID)
		}
	}
}

func sendMessage(nodeID string, msgType string, value int, msgID int) {
	connMutex.RLock()
	conn, ok := nodeConnections[nodeID]
	connMutex.RUnlock()

	if !ok {
		return
	}

	if conn.channelCount > 0 {
		conn.channelCount-- // Remove channel we just allocated
	}

	b := internalMessage{Type: "propagate"}
	data := struct {
		Value int `json:"value"`
		MsgID int `json:"msg_id"`
	}{}
	data.Value = value
	data.MsgID = msgID

	body, _ := json.Marshal(data)
	fullBody := internalMessage{Type: "message", Body: string(body)}

	line := fmt.Sprintf(`{"type": "%s", "body": %s}`, "propagate", fullBody.String())

	// Send to peer via maelstrom RPC
	rpc(nodeID, line)
}

func main() {
	fmt.Fprintf(os.Stderr, "node started with ID: %s\n", nodeID)

	// Run until done
	for {
		msg := bufio.NewScanner(os.Stdin)
		line, err := msg.ReadString('\n')
		if err != nil {
			break
		}

		response := handleMessage(msg)

		// Send response back to client
		jsonResponse, _ := json.Marshal(response)
		fmt.Fprintf(os.Stdout, "%s\n", jsonResponse)
	}

	// Wait for all internal goroutines
	state.wg.Wait()
	fmt.Fprintf(os.Stderr, "node completed\n")
}

