// Client message structures
type broadcastRequest struct {
	MsgID  int `json:"msg_id"`
	Value  int `json:"value"`
}

type broadcastResponse struct {
	InReplyTo int `json:"in_reply_to"`
}

type readRequest struct {
	MsgID int `json:"msg_id"`
}

type readResponse struct {
	InReplyTo   int    `json:"in_reply_to"`
	Messages    []int  `json:"messages"`
}

type topologyRequest struct {
	MsgID int `json:"msg_id"`
}

type topologyResponse struct {
	InReplyTo int `json:"in_reply_to"`
}

// Init message structure
type initMessage struct {
	NodeID       string `json:"node_id"`
	OtherNodes   []string `json:"other_nodes"`
}

// Node state for storing values and managing internal communication
type nodeState struct {
	values        map[int]int // value -> msgID mapping
	hasValue      bool        // whether we have any values to broadcast
	wg            sync.WaitGroup
	cancel        chan struct{}
	nodeID        string
	otherNodes    []string    // IDs of other nodes in the cluster
}

// Internal message type for peer-to-peer communication
type internalMessage struct {
	Type   string `json:"type"`
	Value  int    `json:"value,omitempty"`
	MsgID  int    `json:"msg_id,omitempty"`
	Source string `json:"source,omitempty"` // sender node ID
}

func (m internalMessage) String() string {
	b, _ := json.Marshal(m)
	return string(b)
}

// Global state for node communications
var (
	nodeState = &nodeState{values: make(map[int]int), hasValue: false}
	connections = make(map[string]chan internalMessage)
	connMutex   sync.RWMutex
)

func newConnection(peerID string) chan internalMessage {
	ch := make(chan internalMessage, 100)
	return ch
}

// Handle init message - called once at startup
func (ns *nodeState) handleInit(m *initMessage) error {
	fmt.Fprintf(os.Stderr, "Node initialized: id=%s\n", m.NodeID)

	// Build list of all nodes (including self)
	allNodes := append([]string{m.NodeID}, m.OtherNodes...)
	ns.nodes = allNodes

	// Initialize node-state level structure
	nodeState.nodes = allNodes

	// Set up connections with other nodes
	for _, peerID := range allNodes {
		if peerID != m.NodeID && peerID != "" {
			connMutex.Lock()
			connections[peerID] = newConnection(peerID)
			connMutex.Unlock()

			// Send initial "hello" to announce presence
			ns.sendToPeer(peerID, internalMessage{Type: "hello", Source: m.NodeID})
		}
	}

	return nil
}

// Store a new value received from client
func (ns *nodeState) storeValue(value int, msgID int) {
	ns.values[value] = msgID

	if !ns.hasValue {
		ns.hasValue = true
	}

	// Propagate to all peers that we don't know about yet
	ns.propagateToPeers(msgID)
}

// Get all values this node has stored
func (ns *nodeState) getAllValues() []int {
	values := make([]int, 0, len(ns.values))
	for v := range ns.values {
		values = append(values, v)
	}
	return values
}

// Propagate a value to all connected nodes
func (ns *nodeState) propagateToPeers(msgID int) {
	if !ns.hasValue || len(ns.nodes) == 1 {
		return
	}

	for _, peerID := range ns.nodes {
		if peerID != ns.nodeID && peerID != "" {
			ns.sendToPeer(peerID, internalMessage{Type: "propagate", MsgID: msgID})
		}
	}
}

// Send an internal message to a connected peer node
func (ns *nodeState) sendToPeer(peerID string, msg internalMessage) {
	connMutex.RLock()
	ch, ok := connections[peerID]
	connMutex.RUnlock()

	if !ok {
		return
	}

	select {
	case ch <- msg:
	default:
		// Channel full, skip for now
	}
}

// Process messages from internal channel (runs in a goroutine)
func runInternalLoop(peerID string, ch chan internalMessage) {
	defer func() {
		connMutex.Lock()
		delete(connections, peerID)
		connMutex.Unlock()
		close(ch)
	}()

	for msg := range ch {
		fmt.Fprintf(os.Stderr, "[internal %s] Received: %+v\n", peerID, msg)

		switch msg.Type {
		case "hello":
			// Peer announced itself - just acknowledge
			sendPeerReply(peerID, internalMessage{Type: "hello_ack"})
		case "propagate":
			// Store value if not already known
			storeValueFromPeer(msg.MsgID)
		}
	}
}

// Store a value received from another node (from peer-to-peer propagation)
func storeValueFromPeer(msgID int) {
	value, ok := ns.values[msgID]
	if !ok {
		return // Value already stored or unknown
	}

	ns.hasValue = true

	// Propagate to all peers including the original sender
	propagateMsgToPeers(msgID)
}

// Propagate a message to all connected nodes
func propagateMsgToPeers(msgID int) {
	for _, peerID := range ns.nodes {
		if peerID != ns.nodeID && peerID != "" {
			ns.sendToPeer(peerID, internalMessage{Type: "propagate", MsgID: msgID})
		}
	}
}

// Send a reply response back to the client
func sendClientResponse(msg interface{}) string {
	data, _ := json.Marshal(msg)
	return string(data) + "\n"
}

// Handle broadcast request from client
func handleBroadcast(req broadcastRequest) (interface{}, error) {
	ns.storeValue(req.Value, req.MsgID)

	resp := broadcastResponse{InReplyTo: req.MsgID}
	return resp, nil
}

// Handle read request from client
func handleRead(req readRequest) (interface{}, error) {
	values := ns.getAllValues()

	resp := readResponse{
		InReplyTo:   req.MsgID,
		Messages:    values,
	}
	return resp, nil
}

// Handle topology request from client
func handleTopology(req topologyRequest) (interface{}, error) {
	// We don't need to do anything special here - just acknowledge
	resp := topologyResponse{InReplyTo: req.MsgID}
	return resp, nil
}

func main() {
	fmt.Fprintf(os.Stderr, "Node starting...\n")

	buf := bufio.NewReader(os.Stdin)

	for {
		line, err := buf.ReadString('\n')
		if err != nil {
			break
		}

		msgType := ""
		json.Unmarshal([]byte(line), &msgType)

		switch msgType {
		case "init":
			initMsg := initMessage{}
			json.Unmarshal([]byte(line), &initMsg)

			ns.handleInit(&initMsg)
			ns.wg.Add(1)
			go func() {
				defer ns.wg.Done()

				// Run internal message loop for all peers
				for _, peerID := range ns.nodes {
					if peerID != ns.nodeID && peerID != "" {
						runInternalLoop(peerID, connections[peerID])
					}
				}
			}()

			sendClientResponse(sendClientResponse(nil)) // Acknowledgement

		case "broadcast":
			br := broadcastRequest{}
			json.Unmarshal([]byte(line), &br)

			resp, _ := handleBroadcast(br)
			fmt.Fprintf(os.Stderr, "Broadcast handled: msg_id=%d\n", br.MsgID)

			sendClientResponse(sendClientResponse(resp)) // Send response to client

		case "read":
			rq := readRequest{}
			json.Unmarshal([]byte(line), &rq)

			resp, _ := handleRead(rq)
			fmt.Fprintf(os.Stderr, "Read handled: msg_id=%d\n", rq.MsgID)

			sendClientResponse(sendClientResponse(resp)) // Send response to client

		case "topology":
			tq := topologyRequest{}
			json.Unmarshal([]byte(line), &tq)

			resp, _ := handleTopology(tq)
			fmt.Fprintf(os.Stderr, "Topology handled: msg_id=%d\n", tq.MsgID)

			sendClientResponse(sendClientResponse(resp)) // Send response to client

		default:
			fmt.Fprintf(os.Stderr, "Unknown message type: %s\n", line[:len(line)-1])
		}
	}

	ns.wg.Wait()

	fmt.Fprintf(os.Stderr, "Node finished\n")
}

